import{_ as s,o as t,c as o,a2 as a}from"./chunks/framework.BM5YPQmL.js";const u=JSON.parse('{"title":"Relay tiers","description":"","frontmatter":{},"headers":[],"relativePath":"concepts/relay-tiers.md","filePath":"concepts/relay-tiers.md","lastUpdated":1793739519000}'),i={name:"concepts/relay-tiers.md"};function r(d,e,l,n,c,h){return t(),o("div",null,[...e[0]||(e[0]=[a(`<h1 id="relay-tiers" tabindex="-1">Relay tiers <a class="header-anchor" href="#relay-tiers" aria-label="Permalink to &quot;Relay tiers&quot;">​</a></h1><p>The shell, not the applet, decides which relays a request goes to. It sorts its relays into four tiers, routes each request to one tier by the kinds it asks for, and lets the user edit every tier in Settings. Applets never name a relay for an ordinary query or publish; the one exception is a scoped relay a window opens for itself, described at the end of this page.</p><h2 id="the-four-tiers" tabindex="-1">The four tiers <a class="header-anchor" href="#the-four-tiers" aria-label="Permalink to &quot;The four tiers&quot;">​</a></h2><p>kehto&#39;s <code>RelayConfigHooks</code> knows three tiers: <code>discovery</code>, <code>super</code> and <code>outbox</code>. kernl adds a fourth, <code>apps</code>, for applet manifests. The <code>RelayTier</code> type is the union of the four names.</p><table tabindex="0"><thead><tr><th>Tier</th><th>Settings label</th><th>What it serves</th><th>Default relays (<code>DEFAULT_RELAY_TIERS</code>)</th></tr></thead><tbody><tr><td><code>discovery</code></td><td>Discovery</td><td>Profiles, follow lists and relay lists (kinds <code>0</code>, <code>3</code>, <code>10002</code>)</td><td><code>wss://purplepag.es</code>, <code>wss://relay.nos.social</code></td></tr><tr><td><code>apps</code></td><td>Applet catalogue</td><td>Applet manifests (kehto&#39;s <code>NAPPLET_KINDS</code>, <code>5129</code>, <code>15129</code> and <code>35129</code>, plus the legacy catalogue kind <code>32267</code>)</td><td><code>wss://relay.napplet.soy</code></td></tr><tr><td><code>outbox</code></td><td>Your connections</td><td>Where what the user publishes is delivered</td><td>none</td></tr><tr><td><code>super</code></td><td>General</td><td>Everything that is not discovery or manifests</td><td><code>wss://relay.damus.io</code>, <code>wss://nos.lol</code>, <code>wss://relay.primal.net</code></td></tr></tbody></table><p><code>DEFAULT_RELAY_TIERS</code> is exported from <code>@kernl/core</code> as a frozen <code>TierMap</code>, each tier a frozen array. The outbox tier starts empty: kernl does not guess where the user publishes.</p><h2 id="how-a-request-picks-a-tier" tabindex="-1">How a request picks a tier <a class="header-anchor" href="#how-a-request-picks-a-tier" aria-label="Permalink to &quot;How a request picks a tier&quot;">​</a></h2><p><code>selectRelayTier(tiers, filters)</code> in <code>packages/core/src/applesauce/relay-hooks.ts</code> collects the kinds of every filter and chooses:</p><ol><li>If any filter has no <code>kinds</code>, or an empty <code>kinds</code>, the request cannot be classified and takes the general path.</li><li>If every kind is <code>0</code>, <code>3</code> or <code>10002</code>, the request goes to the <code>discovery</code> tier.</li><li>If every kind is an applet-manifest kind, the request goes to the <code>apps</code> tier.</li><li>Otherwise it goes to <code>super</code> and <code>outbox</code> together.</li></ol><p>The result is deduplicated. A request that mixes a profile kind and a note kind is not split; it takes the general path as a whole.</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">selectRelayTier</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(tiers, [{ kinds: [</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">], authors: [pubkey] }]); </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// tiers.get().discovery</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">selectRelayTier</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(tiers, [{ kinds: [</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">35129</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">] }]);                 </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// tiers.get().apps</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">selectRelayTier</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(tiers, [{ kinds: [</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">] }]);                     </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// super, then outbox</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">selectRelayTier</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(tiers, [{ ids: [id] }]);                      </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// super, then outbox: no kinds</span></span></code></pre></div><p>The same function is used everywhere the shell picks relays on its own:</p><ul><li>kehto&#39;s relay service asks <code>RelayPoolHooks.selectRelayTier</code>, which <code>createRelayPoolHooks</code> answers with this function.</li><li>kernl&#39;s applesauce relay backend (<code>relay-backend.ts</code>) uses it for a subscription or query that names no relays, and for every publish, by the published event&#39;s kind. A published profile therefore goes to the discovery tier, and a published note to <code>super</code> plus <code>outbox</code>.</li><li>Manifest lookups (<code>fetchManifestEvent</code>) ask the relays named in the applet&#39;s address plus the whole <code>apps</code> tier.</li><li>The destructive-write consent lookup, which fetches the current version of a replaceable event before the user is asked, asks <code>outbox</code> plus <code>discovery</code>.</li></ul><h2 id="where-the-configuration-lives" tabindex="-1">Where the configuration lives <a class="header-anchor" href="#where-the-configuration-lives" aria-label="Permalink to &quot;Where the configuration lives&quot;">​</a></h2><p><code>createRelayTiers(storage, defaults?)</code> builds the configuration and returns a <code>RelayTiers</code>: <code>get()</code>, <code>add(tier, url)</code>, <code>remove(tier, url)</code> and <code>changes$</code>. <code>createKernl</code> calls it with <code>host.storage</code> and <code>KernlOptions.relays</code>, and exposes it as <code>kernl.relays</code>.</p><ul><li><strong>Persistence key.</strong> The whole map is written as JSON to <code>kernl:relays:v1</code> (the key <code>relays:v1</code> in a <code>createNamespacedStore</code> with prefix <code>kernl</code>) on every change. See <a href="./persistence">Persistence</a>.</li><li><strong>Start-up.</strong> When <code>kernl:relays:v1</code> holds a value, each tier it names replaces the default for that tier and any tier it lacks keeps <code>DEFAULT_RELAY_TIERS</code>. The host&#39;s <code>KernlOptions.relays</code> is applied over the defaults only when nothing is persisted, so once the user has edited a tier, the host&#39;s overrides no longer apply on that device. A corrupt value reads as absent.</li><li><strong>Validation.</strong> <code>add</code> accepts only <code>ws://</code> or <code>wss://</code> followed by non-space characters and throws <code>invalid:relay-url</code> for anything else. Adding a URL a tier already holds does nothing. <code>remove</code> of a URL the tier does not hold does nothing.</li><li><strong>Observation.</strong> <code>changes$</code> is an RxJS <code>BehaviorSubject</code>, so a new subscriber receives the current map at once. Every value it emits is frozen.</li></ul><h2 id="how-settings-edits-them" tabindex="-1">How Settings edits them <a class="header-anchor" href="#how-settings-edits-them" aria-label="Permalink to &quot;How Settings edits them&quot;">​</a></h2><p>The shell&#39;s Settings panel (<code>apps/web/src/shell/SettingsPanel.svelte</code>) has a Network section with one block per tier, labelled as in the table above. It subscribes to <code>kernl.relays.changes$</code>, lists each server by name with a Remove button that calls <code>kernl.relays.remove</code>, and has a &quot;Server address&quot; field that calls <code>kernl.relays.add</code>. A bare hostname is given the secure scheme before it is added (<code>serverAddress</code> in <code>servers.ts</code>), so typing <code>relay.example</code> stores <code>wss://relay.example</code>. When <code>add</code> throws an <code>invalid:</code> reason the panel asks for a server address; any other failure says the server could not be added.</p><p>The panel never shows the word relay or a protocol scheme to the user (<a href="./../policies/public-vocabulary">Public vocabulary</a>). A change takes effect for the next request; subscriptions already open keep the relays they were opened with.</p><p>The offline preview keeps its own tier state at <code>kernl:preview:relays:v1</code>, so editing tiers in the preview never changes the live shell&#39;s.</p><h2 id="scoped-relays" tabindex="-1">Scoped relays <a class="header-anchor" href="#scoped-relays" aria-label="Permalink to &quot;Scoped relays&quot;">​</a></h2><p>kehto lets a window open one relay of its own choosing, the NIP-29 group pattern. <code>createRelayPoolHooks</code> keeps this minimal: one open subscription per window, replaced when the window opens another, closed with the window, and events delivered to that window&#39;s port only. Publishing to the scoped relay goes to that one relay. Tiers do not apply to scoped relays.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./architecture">Architecture</a></li><li><a href="./persistence">Persistence</a></li><li><a href="./../packages/core"><code>@kernl/core</code></a></li></ul>`,24)])])}const k=s(i,[["render",r]]);export{u as __pageData,k as default};
